// modules/library/components/AuthorForm.js
import { useEffect, useState } from "react";
import { authorApi } from "../api/authorApi";
import { useParams, useNavigate } from "react-router-dom";

const COUNTRIES = [
  "Ethiopia", "American", "British", "Canadian", "French", "German",
  "Japanese", "Chinese", "Indian", "Australian", "Spanish",
  "Italian", "Russian", "Brazilian", "Mexican", "Other"
];

export default function AuthorForm({ method }) {
  const { id } = useParams();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);

  const [form, setForm] = useState({
    first_name: "",
    last_name: "",
    biography: "",
    nationality: "",
    date_of_birth: "",
    website: "",
    email: "",
    phone: "",
    affiliation: "",
    profile_picture: null,
    social_links: "",
    status: "active"
  });

  const isCreate = method === "create";
  const isEdit = method === "edit";

  useEffect(() => {
    if (isEdit) {
      setLoading(true);
      authorApi.get(`/${id}`)
        .then(res => {
          const data = res.data;
          setForm({
            ...data,
            social_links: data.social_links ? data.social_links.join(",") : "",
            profile_picture: null // don't preload file input
          });
          setLoading(false);
        })
        .catch(() => setLoading(false));
    }
  }, [id, isEdit]);

  const handleChange = e => {
    const { name, value, files } = e.target;
    if (files) {
      setForm(prev => ({ ...prev, [name]: files[0] }));
    } else {
      setForm(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleSubmit = async e => {
    e.preventDefault();
    setLoading(true);

    try {
      const fd = new FormData();
      Object.entries(form).forEach(([k, v]) => {
        if (k === "social_links") fd.append(k, JSON.stringify(v.split(",").map(s => s.trim())));
        else fd.append(k, v);
      });

      if (isCreate) await authorApi.post("/", fd);
      else await authorApi.put(`/${id}`, fd);

      navigate("/library/author");
    } catch (error) {
      console.error("Error saving author:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleReset = () => {
    if (isCreate) {
      setForm({
        first_name: "",
        last_name: "",
        biography: "",
        nationality: "",
        date_of_birth: "",
        website: "",
        email: "",
        phone: "",
        affiliation: "",
        profile_picture: null,
        social_links: "",
        status: "active"
      });
    }
  };

  return (
    <div className="content-header">
      <section className="content">
        <div className="container-fluid">
          <div className="row">
            <div className="col-lg-8 offset-lg-2">
              {loading && isEdit ? (
                <div className="card">
                  <div className="card-body text-center py-5">
                    <div className="spinner-border text-primary" role="status">
                      <span className="sr-only">Loading...</span>
                    </div>
                    <p className="mt-3">Loading author details...</p>
                  </div>
                </div>
              ) : (
                <div className="card card-primary card-outline">
                  <div className="card-header">
                    <h3 className="card-title">
                      <i className="fas fa-user-edit mr-2"></i>
                      Author Information
                    </h3>
                  </div>
                  
                  <form onSubmit={handleSubmit}>
                    <div className="card-body">

                      {/* Name */}
                      <div className="row">
                        <div className="col-md-6">
                          <input type="text" className="form-control mb-2" placeholder="First Name *" name="first_name"
                            value={form.first_name} onChange={handleChange} required disabled={loading} />
                        </div>
                        <div className="col-md-6">
                          <input type="text" className="form-control mb-2" placeholder="Last Name *" name="last_name"
                            value={form.last_name} onChange={handleChange} required disabled={loading} />
                        </div>
                      </div>

                      {/* Nationality & Date of Birth */}
                      <div className="row">
                        <div className="col-md-6">
                          <select className="form-control mb-2" name="nationality" value={form.nationality} onChange={handleChange} disabled={loading}>
                            <option value="">Select Nationality</option>
                            {COUNTRIES.map(c => <option key={c} value={c}>{c}</option>)}
                          </select>
                        </div>
                        <div className="col-md-6">
                          <input type="date" className="form-control mb-2" name="date_of_birth" value={form.date_of_birth || ""} onChange={handleChange} disabled={loading} />
                        </div>
                      </div>

                      {/* Website, Email, Phone */}
                      <input type="url" className="form-control mb-2" placeholder="Website" name="website" value={form.website} onChange={handleChange} disabled={loading} />
                      <input type="email" className="form-control mb-2" placeholder="Email" name="email" value={form.email} onChange={handleChange} disabled={loading} />
                      <input type="text" className="form-control mb-2" placeholder="Phone" name="phone" value={form.phone} onChange={handleChange} disabled={loading} />

                      {/* Affiliation */}
                      <input type="text" className="form-control mb-2" placeholder="Affiliation" name="affiliation" value={form.affiliation} onChange={handleChange} disabled={loading} />

                      {/* Profile Picture */}
                      <div className="form-group mb-2">
                        <label>Profile Picture</label>
                        <input type="file" className="form-control-file" name="profile_picture" onChange={handleChange} disabled={loading} />
                      </div>

                      {/* Social Links */}
                      <input type="text" className="form-control mb-2" placeholder="Social Links (comma separated)" name="social_links" value={form.social_links} onChange={handleChange} disabled={loading} />

                      {/* Status */}
                      <select className="form-control mb-2" name="status" value={form.status} onChange={handleChange} disabled={loading}>
                        <option value="active">Active</option>
                        <option value="inactive">Inactive</option>
                      </select>

                      {/* Biography */}
                      <textarea className="form-control mb-2" rows={5} placeholder="Biography" name="biography" value={form.biography} onChange={handleChange} disabled={loading}></textarea>

                    </div>

                    {/* Footer Buttons */}
                    <div className="card-footer">
                      <div className="row">
                        <div className="col-md-4 mb-2">
                          <button type="button" className="btn btn-secondary btn-block" onClick={() => navigate("/library/author")} disabled={loading}>
                            Cancel
                          </button>
                        </div>
                        <div className="col-md-4 mb-2">
                          <button type="button" className="btn btn-warning btn-block" onClick={handleReset} disabled={loading || isEdit}>
                            Reset
                          </button>
                        </div>
                        <div className="col-md-4">
                          <button type="submit" className="btn btn-primary btn-block" disabled={loading}>
                            {loading ? "Saving..." : "Save Author"}
                          </button>
                        </div>
                      </div>
                    </div>

                  </form>
                </div>
              )}
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}
